/// Turns a checked [I18nSource] into the generated files' contents.
library;

import 'dart:convert';

import 'model.dart';

const _header =
    '// GENERATED by tools/i18n/build.dart from i18n/*.json. '
    'Do not edit by hand;\n'
    '// edit i18n/te.json, en.json and meta.json and run '
    '`melos run gen:l10n`.\n';

/// Package that bundles the recorded voice prompts (see orbit_voice).
const voicePackage = 'orbit_voice';

/// Asset path of [key]'s prompt inside [voicePackage].
String voiceAssetPath(String key) => 'assets/voice/te/$key.m4a';

/// Encodes [value] as stable, sorted, 2-space JSON with a final newline.
String canonicalJson(Object? value) =>
    '${const JsonEncoder.withIndent('  ').convert(_sorted(value))}\n';

Object? _sorted(Object? v) {
  if (v is Map) {
    final keys = v.keys.cast<String>().toList()..sort();
    return {for (final k in keys) k: _sorted(v[k])};
  }
  if (v is List) return v.map(_sorted).toList();
  return v;
}

/// The ARB file for [locale]. Only the template (te) carries `@key` metadata.
String arb(I18nSource src, String locale) {
  final strings = locale == 'te' ? src.te : src.en;
  final out = <String, Object?>{'@@locale': locale};
  for (final key in src.te.keys) {
    final text = strings[key];
    if (text == null) continue;
    final name = arbName(key);
    out[name] = text;
    if (locale != 'te') continue;
    final meta = src.meta[key]!;
    out['@$name'] = {
      'description': meta.description,
      if (meta.placeholders.isNotEmpty)
        'placeholders': {
          for (final p in meta.placeholders.values) p.name: _sorted(p.raw),
        },
      'x-key': key,
      'x-screen': meta.screen,
    };
  }
  return '${const JsonEncoder.withIndent('  ').convert(out)}\n';
}

String _dartString(String s) =>
    "'${s.replaceAll(r'\', r'\\').replaceAll("'", r"\'").replaceAll(r'$', r'\$')}'";

/// `lib/src/voice_keys.g.dart` in orbit_l10n.
String voiceKeysDart(I18nSource src) {
  final keys = src.voiceKeys;
  final recorded = src.recordedVoiceKeys;
  final b = StringBuffer()
    ..write(_header)
    ..writeln()
    ..writeln('/// Package whose assets hold the recorded Telugu prompts.')
    ..writeln("const String voiceAssetPackage = '$voicePackage';")
    ..writeln()
    ..writeln(
      '/// Every i18n key marked `voice: true` in meta.json. '
      'A Listen button plays the',
    )
    ..writeln('/// prompt recorded for one of these keys.')
    ..writeln('abstract final class VoiceKeys {');
  for (final k in keys) {
    b
      ..writeln('  /// ${src.te[k]!.replaceAll('\n', ' ')}')
      ..writeln('  static const String ${arbName(k)} = ${_dartString(k)};')
      ..writeln();
  }
  b
    ..writeln('  /// Every voice key, sorted.')
    ..writeln('  static const List<String> all = <String>[');
  for (final k in keys) {
    b.writeln('    ${arbName(k)},');
  }
  b
    ..writeln('  ];')
    ..writeln('}')
    ..writeln()
    ..writeln(
      '/// Asset path (inside [voiceAssetPackage]) for every voice key, '
      'recorded or not.',
    )
    ..writeln('const Map<String, String> voiceAssetPaths = <String, String>{');
  for (final k in keys) {
    b.writeln('  ${_dartString(k)}: ${_dartString(voiceAssetPath(k))},');
  }
  b
    ..writeln('};')
    ..writeln()
    ..writeln(
      '/// Voice keys whose recording is bundled in orbit_voice '
      '(${recorded.length} of ${keys.length}).',
    )
    ..write('const Set<String> recordedVoiceKeys = <String>{');
  if (recorded.isNotEmpty) b.writeln();
  for (final k in recorded) {
    b.writeln('  ${_dartString(k)},');
  }
  b.writeln('};');
  return b.toString();
}

/// Name of the generated label helper for an enum [schema]:
/// `visit_status` -> `labelVisitStatus`. The `label` prefix keeps it clear of
/// the ARB getters, which all start with a surface (`common`, `farmer`, ...).
String enumHelperName(String schema) => arbName('label.$schema');

/// `lib/src/lookups.g.dart` in orbit_l10n: error and enum lookups by string.
String lookupsDart(I18nSource src) {
  final errors = <String, String>{}; // code -> getter
  final details = <String, Placeholder>{}; // detail field -> placeholder
  final enums = <String, Map<String, String>>{}; // schema -> value -> getter
  for (final key in src.te.keys) {
    final parts = key.split('.');
    if (parts.first == 'error' && parts.length == 2) {
      errors[parts[1]] = arbName(key);
    } else if (parts.first == 'error' &&
        parts.length == 3 &&
        parts[1] == 'detail') {
      details[parts[2]] = src.meta[key]!.placeholders.values.single;
    } else if (parts.first == 'enum' && parts.length == 3) {
      (enums[parts[1]] ??= {})[parts[2]] = arbName(key);
    }
  }
  final schemas = enums.keys.toList()..sort();

  final b = StringBuffer()
    ..write(_header)
    ..writeln()
    ..writeln("import '../l10n/generated/orbit_localizations.dart';")
    ..writeln()
    ..writeln('/// Every `error.<code>` key, by code.')
    ..writeln('const Set<String> knownErrorCodes = <String>{');
  for (final c in errors.keys) {
    b.writeln('  ${_dartString(c)},');
  }
  b
    ..writeln('};')
    ..writeln()
    ..writeln('/// Every `enum.<schema>.<value>` key: schema -> values.')
    ..writeln(
      'const Map<String, List<String>> enumSchemas = '
      '<String, List<String>>{',
    );
  for (final s in schemas) {
    b.writeln('  ${_dartString(s)}: <String>[');
    for (final v in enums[s]!.keys) {
      b.writeln('    ${_dartString(v)},');
    }
    b.writeln('  ],');
  }
  b
    ..writeln('};')
    ..writeln()
    ..writeln('/// Text of `error.<code>`, or null when there is no such key.')
    ..writeln(
      'String? errorMessageFor(OrbitLocalizations l10n, String code) =>',
    )
    ..writeln('    switch (code) {');
  for (final e in errors.entries) {
    b.writeln('      ${_dartString(e.key)} => l10n.${e.value},');
  }
  b
    ..writeln('      _ => null,')
    ..writeln('    };')
    ..writeln()
    ..writeln(
      '/// Sentence of `error.detail.<field>` for a details value, or '
      'null when there',
    )
    ..writeln('/// is no such key or [value] does not fit its placeholder.')
    ..writeln('String? errorDetailFor(')
    ..writeln('  OrbitLocalizations l10n,')
    ..writeln('  String field,')
    ..writeln('  Object? value,')
    ..writeln(') {')
    ..writeln('  switch (field) {');
  for (final d in details.entries) {
    final getter = arbName('error.detail.${d.key}');
    final p = d.value;
    final conv = switch (p.type) {
      'int' => '_asInt(value)',
      'num' || 'double' => '_asNum(value)',
      _ => "value?.toString()",
    };
    b
      ..writeln('    case ${_dartString(d.key)}:')
      ..writeln('      final v = $conv;')
      ..writeln('      return v == null ? null : l10n.$getter(${p.name}: v);');
  }
  b
    ..writeln('  }')
    ..writeln('  return null;')
    ..writeln('}')
    ..writeln()
    ..writeln('int? _asInt(Object? v) => switch (v) {')
    ..writeln('      final int i => i,')
    ..writeln('      final num n => n.toInt(),')
    ..writeln('      final String s => int.tryParse(s.trim()),')
    ..writeln('      _ => null,')
    ..writeln('    };')
    ..writeln()
    ..writeln('// ignore: unused_element')
    ..writeln('num? _asNum(Object? v) => switch (v) {')
    ..writeln('      final num n => n,')
    ..writeln('      final String s => num.tryParse(s.trim()),')
    ..writeln('      _ => null,')
    ..writeln('    };')
    ..writeln()
    ..writeln(
      '/// Label of `enum.<schema>.<value>`, or null when there is no '
      'such key.',
    )
    ..writeln('String? enumLabelFor(')
    ..writeln('  OrbitLocalizations l10n,')
    ..writeln('  String schema,')
    ..writeln('  String value,')
    ..writeln(') =>')
    ..writeln(r"    switch ('$schema.$value') {");
  for (final s in schemas) {
    for (final v in enums[s]!.entries) {
      b.writeln("      ${_dartString('$s.${v.key}')} => l10n.${v.value},");
    }
  }
  b
    ..writeln('      _ => null,')
    ..writeln('    };')
    ..writeln()
    ..writeln(
      '/// One label helper per enum schema. Each takes the API string '
      'value and',
    )
    ..writeln(
      '/// falls back to [OrbitLocalizations.commonUnknown] for a value '
      'this app',
    )
    ..writeln('/// version has no label for.')
    ..writeln('extension OrbitEnumLabels on OrbitLocalizations {')
    ..writeln(
      '  /// Label of `enum.<schema>.<value>`, or null when this app '
      'version has none.',
    )
    ..writeln('  String? enumLabel(String schema, String value) =>')
    ..writeln('      enumLabelFor(this, schema, value);');
  for (final s in schemas) {
    final values = enums[s]!.keys.map((v) => '`$v`').join(', ');
    b
      ..writeln()
      ..writeln('  /// Label for a `$s` value ($values).')
      ..writeln('  String ${enumHelperName(s)}(String value) =>')
      ..writeln(
        "      enumLabelFor(this, ${_dartString(s)}, value) ?? "
        'commonUnknown;',
      );
  }
  b.writeln('}');
  return b.toString();
}

/// `test/all_messages.g.dart` in orbit_l10n: every message rendered with
/// sample arguments, so tests can check that each key resolves in each locale.
String allMessagesTestDart(I18nSource src) {
  final b = StringBuffer()
    ..write(_header)
    ..writeln()
    ..writeln("import 'package:orbit_l10n/orbit_l10n.dart';")
    ..writeln()
    ..writeln(
      '/// i18n key -> the message rendered with sample arguments '
      '(placeholder',
    )
    ..writeln(
      '/// `example` from meta.json, 2 for numbers, 29 Oct 2026 07:05 '
      'for dates).',
    )
    ..writeln(
      'final Map<String, String Function(OrbitLocalizations)> '
      'allMessages =',
    )
    ..writeln('    <String, String Function(OrbitLocalizations)>{');
  for (final key in src.te.keys) {
    final meta = src.meta[key]!;
    final name = arbName(key);
    if (meta.placeholders.isEmpty) {
      b.writeln('  ${_dartString(key)}: (l) => l.$name,');
      continue;
    }
    final args = [
      for (final p in meta.placeholders.values)
        '${p.name}: ${switch (p.type) {
          'int' => '2',
          'num' || 'double' => '2.5',
          'DateTime' => 'DateTime(2026, 10, 29, 7, 5)',
          _ => _dartString(p.example ?? p.name),
        }}',
    ];
    b.writeln('  ${_dartString(key)}: (l) => l.$name(${args.join(', ')}),');
  }
  b.writeln('};');
  return b.toString();
}
